[CmdletBinding()]
param([string]$BundlesDirectory='ES/Output/WebPageStudio/bundles',[string]$OutputPath='')
$ErrorActionPreference='Stop';$OutputEncoding=[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false);$root=[IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\')+'\';$readiness=& (Join-Path $root 'ES/Automation/WebPageStudio/Test-ESWebPageStudioBundleReplayReadiness.ps1') -BundlesDirectory $BundlesDirectory|ConvertFrom-Json;$freshness=& (Join-Path $root 'ES/Automation/WebPageStudio/Test-ESWebPageStudioAllBundlesFreshness.ps1') -BundlesDirectory $BundlesDirectory|ConvertFrom-Json;$report=[ordered]@{schemaVersion=1;recordType='WebPageStudioMigrationEvidenceReport';status=if($readiness.notReadyCount -eq 0 -and $freshness.staleBundleCount -eq 0){'ready'}else{'partial'};generatedUtc=[DateTime]::UtcNow.ToString('o');scope=$BundlesDirectory;replayReadiness=[ordered]@{bundleCount=$readiness.bundleCount;readyCount=$readiness.readyCount;notReadyCount=$readiness.notReadyCount;bundles=$readiness.bundles};freshness=[ordered]@{bundleCount=$freshness.bundleCount;passedBundleCount=$freshness.passedBundleCount;staleBundleCount=$freshness.staleBundleCount;bundles=$freshness.bundles;sourceHashes=$freshness.sourceHashes};nonClaims=@('This report does not rewrite historical artifacts.','This report does not prove browser, backend, Unity, or production runtime behavior.')};if($OutputPath){$out=[IO.Path]::GetFullPath((Join-Path $root $OutputPath));if(-not $out.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){throw 'OutputPath must remain under project root.'};[IO.File]::WriteAllText($out,($report|ConvertTo-Json -Depth 15),[Text.UTF8Encoding]::new($false));$report.reportPath=$out.Replace($root,'').Replace('\','/')};$report|ConvertTo-Json -Depth 15
